s.human_revisions=Number(s.human_revisions||0)+1;s.auto_revisions=0;s.revision=Number(s.revision||0)+1;s.needs_feedback=false;
const sections=articleSections(String(s.article?.content_html||''));
const norm=v=>String(v||'').normalize('NFC').replace(/[\u064B-\u065F\u0670\u0640]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/[^\p{L}\p{N}\s]/gu,' ').replace(/\s+/g,' ').trim();
const note=norm(s.feedback),target=s.revision_target||'تحديد تلقائي من الملاحظات';
let selected=sections,fields=[];
if(target.startsWith('section_')){
 const id=target.split('|')[0].trim();selected=sections.filter(x=>x.id===id);
 if(!selected.length)throw new Error('Requested section does not belong to this article revision');
}else if(['العنوان الرئيسي فقط','عنوان SEO فقط','وصف الميتا فقط'].includes(target)){
 selected=[];fields=[{'العنوان الرئيسي فقط':'title','عنوان SEO فقط':'seo_title','وصف الميتا فقط':'meta_description'}[target]];
}else if(target!=='كل نص المقال'){
 const named=sections.filter(x=>{
  const head=norm(x.heading);
  if(head&&note.includes(head))return true;
  if(head.includes('الخلاصه القانونيه'))return note.includes('الخلاصه');
  if(head.includes('الاسئله الشائعه'))return note.includes('الاسئله الشائعه');
  if(head.startsWith('الخاتمه'))return note.includes('الخاتمه');
  return false;
 });
 if(named.length)selected=named;
 else if(note.includes('عنوان seo')||note.includes('عنوان السيو')){selected=[];fields=['seo_title'];}
 else if(note.includes('وصف الميتا')){selected=[];fields=['meta_description'];}
 else if(note.includes('العنوان الرئيسي')||note.includes('عنوان المقال')){selected=[];fields=['title'];}
}
const mode=s.revision_scope==='text_and_images'?'text_and_images':'text_only';
