function guardCost(state,costs,next,stage,provider='openai'){
 if(!['openai','serpapi'].includes(provider)||!Number.isFinite(next)||next<0)throw Error('Invalid provider cost allowance');
 const budget=Number(state.settings?.article_budget_usd??0.70),ledger=mergeCosts(costs),reserve=imageReserveUsd(state,ledger);
 if(!Number.isFinite(budget)||budget<=0||budget>0.70||!Number.isFinite(reserve)||reserve<0)throw Error('Invalid total article cost configuration; maximum is $0.70');
 if(ledger.events.some(e=>!Number.isFinite(Number(e.usd))||Number(e.usd)<0))throw Error('Invalid article cost ledger');
 if(ledger.total_usd+next+reserve>budget+1e-9)throw Error('[budget:total] '+stage+' stopped before request. Total spent/estimated $'+ledger.total_usd.toFixed(4)+', request allowance $'+next.toFixed(4)+', image allowance $'+reserve.toFixed(4)+', total article budget $'+budget.toFixed(2)+'. Includes OpenAI and SerpApi. Existing article and usage remain in execution data.');
}
function reserveTextRequest(state,costs,payload,stage){
 const rates=TEXT_RATES[payload.model];
 if(!rates)throw Error('Missing model pricing: '+payload.model);
 const budget=Number(state.settings?.article_budget_usd??0.70),ledger=mergeCosts(costs),reserve=imageReserveUsd(state,ledger);
