// Reduce percent-encoded URL text in model input. Original URLs remain in state;
// the usage recorder restores exact URLs in structured model output.
function compactPromptUrls(prompt){
 const original=JSON.parse(prompt),mapping=new Map(),ambiguous=new Set();
 const candidate=v=>{
  if(typeof v!=='string'||!/^https?:\/\/[^\s<>"']+$/.test(v)||!/%[a-f\d]{2}/i.test(v))return v;
  try{const decoded=decodeURI(v);return /[\s<>"'\u0000-\u001f\u007f]/.test(decoded)?v:decoded;}catch{return v;}
 };
 function collect(v){if(typeof v==='string'){const d=candidate(v);if(mapping.has(d)&&mapping.get(d)!==v)ambiguous.add(d);else mapping.set(d,v);}
  else if(Array.isArray(v))v.forEach(collect);else if(v&&typeof v==='object')Object.values(v).forEach(collect);}
 collect(original);
 function pack(v){if(typeof v==='string'){const d=candidate(v);return ambiguous.has(d)?v:d;}
  if(Array.isArray(v))return v.map(pack);if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,x])=>[k,pack(x)]));return v;}
 const reverse=Object.fromEntries([...mapping].filter(([d,v])=>d!==v&&!ambiguous.has(d)));
 return {prompt:JSON.stringify(pack(original)),reverse};
}
function restorePromptUrls(output,reverse){
 if(!output||!reverse||!Object.keys(reverse).length)return output;
 function unpack(v){if(typeof v==='string')return Object.prototype.hasOwnProperty.call(reverse,v)?reverse[v]:v;
  if(Array.isArray(v))return v.map(unpack);if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,x])=>[k,unpack(x)]));return v;}
 try{return JSON.stringify(unpack(JSON.parse(output)));}catch{return output;}
}

const TEXT_RATES={'gpt-4o-mini':{input:0.15,cached:0.075,output:0.60},'gpt-4.1-mini':{input:0.40,cached:0.10,output:1.60},'gpt-4.1':{input:2,cached:0.5,output:8}};
function mergeCosts(...ledgers){
 const events=[...new Map(ledgers.filter(Boolean).flatMap(c=>c.events||[]).map(e=>[e.id,e])).values()];
 const sum=provider=>Number(events.filter(e=>!provider||e.provider===provider).reduce((s,e)=>s+Number(e.usd||0),0).toFixed(8));
 const openaiUsd=sum('openai');
 return {version:'1.1',pricing_date:'2026-10-13',currency:'USD',events,total_usd:sum(),openai_usd:openaiUsd,serpapi_usd:sum('serpapi'),serpapi_credits:events.filter(e=>e.provider==='serpapi').reduce((s,e)=>s+Number(e.credits||0),0),budget_scope:'total',budget_spent_usd:sum(),basis:'OpenAI provider tokens at public list prices; SerpApi searches at configured allocated subscription rate; direct HTML reads have no provider API fee. Article budget includes OpenAI and SerpApi. Excludes hosting, taxes and account discounts.',unconfirmed:events.some(e=>/unconfirmed|estimate/.test(e.basis||''))};
}
function imageReserveUsd(state,costs){
 return state.reuse_existing_images||costs.events.some(e=>e.provider==='openai'&&e.stage==='Composite Image')?0:Number(state.settings?.image_budget_reserve_usd??0.12);
}
function guardCost(state,costs,next,stage,provider='openai'){
 if(!['openai','serpapi'].includes(provider)||!Number.isFinite(next)||next<0)throw Error('Invalid provider cost allowance');
 const budget=Number(state.settings?.article_budget_usd??0.70),ledger=mergeCosts(costs),reserve=imageReserveUsd(state,ledger);
 if(!Number.isFinite(budget)||budget<=0||budget>0.70||!Number.isFinite(reserve)||reserve<0)throw Error('Invalid total article cost configuration; maximum is $0.70');
 if(ledger.events.some(e=>!Number.isFinite(Number(e.usd))||Number(e.usd)<0))throw Error('Invalid article cost ledger');
 if(ledger.total_usd+next+reserve>budget+1e-9)throw Error('[budget:total] '+stage+' stopped before request. Total spent/estimated $'+ledger.total_usd.toFixed(4)+', request allowance $'+next.toFixed(4)+', image allowance $'+reserve.toFixed(4)+', total article budget $'+budget.toFixed(2)+'. Includes OpenAI and SerpApi. Existing article and usage remain in execution data.');
}
function reserveTextRequest(state,costs,payload,stage){
 const rates=TEXT_RATES[payload.model];
 if(!rates)throw Error('Missing model pricing: '+payload.model);
 const budget=Number(state.settings?.article_budget_usd??0.70),ledger=mergeCosts(costs),reserve=imageReserveUsd(state,ledger);
 const inputUpper=(Buffer.byteLength(JSON.stringify(payload),'utf8')+1024)*rates.input/1e6;
 const available=budget-ledger.total_usd-reserve-inputUpper;
 const affordable=Math.floor((available-1e-8)*1e6/rates.output);
 const minima={'Article Writer':3072,'Humanizer':4096,'Legal Meaning Check':1024,'Final Article Review':2048,'Research Questions':1024,'Research Synthesis':2048,'Fallback Image Plan':1024};
 const minimum=Math.min(payload.max_output_tokens,minima[stage]||1024);
 if(!Number.isFinite(affordable)||affordable<minimum)throw Error('[budget:total] '+stage+' stopped before request: insufficient remaining allowance for a complete response.');
 payload.max_output_tokens=Math.min(payload.max_output_tokens,affordable);
 const upper=inputUpper+payload.max_output_tokens*rates.output/1e6;
 guardCost(state,costs,upper,stage);
 return upper;
}

const p=$("Prepare Fallback Image Plan Request").itemMatching(0).json,b=$json.body??$json,u=b.usage;const c=mergeCosts(p.cost_tracking);
const rates=TEXT_RATES[p.payload.model];const measured=u&&Number.isFinite(u.input_tokens)&&Number.isFinite(u.output_tokens);
const cached=measured?Math.min(u.input_tokens,Number(u.input_tokens_details?.cached_tokens||0)):0;
const usd=measured?((u.input_tokens-cached)*rates.input+cached*rates.cached+u.output_tokens*rates.output)/1e6:p.reserved_usd;
const event={id:String($execution.id)+':'+"Fallback Image Plan"+':'+$runIndex,provider:'openai',stage:p.stage,instruction_sets:p.instruction_sets,model:b.model||p.payload.model,request_id:b.id||$json.headers?.['x-request-id']||null,usage:u||null,usd,basis:measured?'provider_tokens_at_list_price':'unconfirmed_request_reserve',status:b.status||String($json.statusCode||'unknown')};
c.events.push(event);const costs=mergeCosts(c);
const rawOutput=(b.output||[]).filter(x=>x.type==='message').flatMap(x=>x.content||[]).filter(x=>x.type==='output_text').map(x=>x.text).join('');
const output=restorePromptUrls(rawOutput,p.url_transport);
const problem=b.status!=='completed'||!output||b.error;
return [{json:{output,cost_tracking:costs,provider_error:problem?('OpenAI '+p.stage+': '+(b.error?.message||b.incomplete_details?.reason||b.status||'missing output')):null},pairedItem:{item:0}}];
